// All symbols below were verified via javap/Vineflower against the 26.2 loom jars in this run.
import net.minecraft.client.Minecraft;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.item.ItemStack;

public final class HotbarProbe {

    public static void probe() {
        Minecraft mc = Minecraft.getInstance();
        LocalPlayer player = mc.player;
        if (player == null) return;

        Inventory inv = player.getInventory();   // exact type: net.minecraft.world.entity.player.Inventory

        // --- read the selected hotbar slot ---
        int selected = inv.getSelectedSlot();                 // 0..8
        ItemStack held = inv.getSelectedItem();               // identical to player.getMainHandItem()
        ItemStack offhand = player.getOffhandItem();          // == inv.getItem(Inventory.SLOT_OFFHAND)
        ItemStack mainByHand = player.getItemInHand(InteractionHand.MAIN_HAND);

        // --- walk the hotbar by index ---
        for (int i = 0; i < Inventory.SELECTION_SIZE; i++) {  // SELECTION_SIZE == 9
            ItemStack stack = inv.getItem(i);
            if (!stack.isEmpty()) {
                // stack.getItem(), stack.getCount()
            }
        }

        // --- find something and switch to it, guarding the throwing setter ---
        int found = inv.findSlotMatchingItem(held);           // scans slots 0..35 only
        if (found != Inventory.NOT_FOUND_INDEX && Inventory.isHotbarSlot(found)) {
            inv.setSelectedSlot(found);                      // throws IllegalArgumentException outside 0..8
            // MultiPlayerGameMode.tick() -> ensureHasSentCarriedItem() will send
            // ServerboundSetCarriedItemPacket on the next client tick. Nothing to do here
            // UNLESS you revert the slot within this same tick.
        }

        // --- interaction ranges (attribute-backed doubles) ---
        double blockReach  = player.blockInteractionRange();  // 4.5 survival / 5.0 creative
        double entityReach = player.entityInteractionRange(); // 3.0 survival / 5.0 creative

        // --- InteractionResult is a sealed interface, not an enum ---
        if (mc.gameMode != null) {
            InteractionResult result = mc.gameMode.useItem(player, InteractionHand.MAIN_HAND);
            boolean consumed = result.consumesAction();
            if (result instanceof InteractionResult.Success success) {
                InteractionResult.SwingSource swing = success.swingSource();
                boolean wasItem = success.wasItemInteraction();
                ItemStack transformed = success.heldItemTransformedTo(); // @Nullable
            } else if (result == InteractionResult.PASS || result == InteractionResult.FAIL) {
                // nothing happened
            }
        }

        // restore the original selection
        if (Inventory.isHotbarSlot(selected)) {
            inv.setSelectedSlot(selected);
        }
    }
}
